import ctypes
import os
from ctypes import wintypes
from pathlib import Path
from typing import TYPE_CHECKING, Final, NoReturn, final

if TYPE_CHECKING or os.name == "nt":
    import msvcrt

FILE_ATTRIBUTE_REPARSE_POINT: Final = 0x400
FILE_ATTRIBUTE_NORMAL: Final = 0x80
FILE_FLAG_OPEN_REPARSE_POINT: Final = 0x00200000
GENERIC_READ: Final = 0x80000000
FILE_SHARE_ALL: Final = 0x00000007
OPEN_EXISTING: Final = 3


@final
class _FileTime(ctypes.Structure):
    """Win32 FILETIME layout used by BY_HANDLE_FILE_INFORMATION."""

    _fields_ = (("low", wintypes.DWORD), ("high", wintypes.DWORD))


@final
class _ByHandleFileInformation(ctypes.Structure):
    """Minimal GetFileInformationByHandle output including immutable attributes."""

    _fields_ = (
        ("attributes", wintypes.DWORD),
        ("creation_time", _FileTime),
        ("last_access_time", _FileTime),
        ("last_write_time", _FileTime),
        ("volume_serial_number", wintypes.DWORD),
        ("file_size_high", wintypes.DWORD),
        ("file_size_low", wintypes.DWORD),
        ("number_of_links", wintypes.DWORD),
        ("file_index_high", wintypes.DWORD),
        ("file_index_low", wintypes.DWORD),
    )


class _WindowsSecureOpenUnavailableError(OSError):
    pass


class _ReparsePointOpenError(OSError):
    pass


def _raise_last_error(operation: str) -> NoReturn:
    """Raise the current Win32 error as an OSError the discovery boundary converts."""
    raise OSError(ctypes.get_last_error(), operation)


if TYPE_CHECKING:

    def _native_open_handle(_path: Path) -> wintypes.HANDLE: ...

    def _native_handle_attributes(_handle: wintypes.HANDLE) -> int: ...

    def _native_close_handle(_handle: wintypes.HANDLE) -> None: ...

else:

    def _native_open_handle(path: Path) -> wintypes.HANDLE:
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        create_file = kernel32.CreateFileW
        create_file.argtypes = (
            wintypes.LPCWSTR,
            wintypes.DWORD,
            wintypes.DWORD,
            wintypes.LPVOID,
            wintypes.DWORD,
            wintypes.DWORD,
            wintypes.HANDLE,
        )
        create_file.restype = wintypes.HANDLE
        return wintypes.HANDLE(
            create_file(
                str(path),
                GENERIC_READ,
                FILE_SHARE_ALL,
                None,
                OPEN_EXISTING,
                FILE_ATTRIBUTE_NORMAL | FILE_FLAG_OPEN_REPARSE_POINT,
                None,
            )
        )

    def _native_handle_attributes(handle: wintypes.HANDLE) -> int:
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        get_information = kernel32.GetFileInformationByHandle
        get_information.argtypes = (wintypes.HANDLE, ctypes.POINTER(_ByHandleFileInformation))
        get_information.restype = wintypes.BOOL
        information = _ByHandleFileInformation()
        if not get_information(handle, ctypes.byref(information)):
            _raise_last_error("GetFileInformationByHandle")
        return int(information.attributes)

    def _native_close_handle(handle: wintypes.HANDLE) -> None:
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        close_handle = kernel32.CloseHandle
        close_handle.argtypes = (wintypes.HANDLE,)
        close_handle.restype = wintypes.BOOL
        close_handle(handle)


def _open_handle(path: Path) -> wintypes.HANDLE:
    """Open the path itself with FILE_FLAG_OPEN_REPARSE_POINT rather than its target."""
    handle = _native_open_handle(path)
    if handle.value == -1:
        _raise_last_error("CreateFileW")
    return handle


def handle_attributes(handle: wintypes.HANDLE) -> int:
    """Read attributes from the exact Win32 handle that will supply document bytes."""
    return _native_handle_attributes(handle)


def _close_handle(handle: wintypes.HANDLE) -> None:
    """Close a native handle only when CRT descriptor ownership was not transferred."""
    _native_close_handle(handle)


def open_read_descriptor(path: Path) -> int:
    """Return a CRT descriptor only after the opened Win32 handle is not a reparse point."""
    if os.name != "nt":
        raise _WindowsSecureOpenUnavailableError

    handle = _open_handle(path)
    handle_owned = True
    try:
        if handle_attributes(handle) & FILE_ATTRIBUTE_REPARSE_POINT:
            raise _ReparsePointOpenError
        handle_value = handle.value
        if handle_value is None:
            _raise_last_error("CreateFileW returned an invalid handle")
        descriptor = msvcrt.open_osfhandle(handle_value, os.O_RDONLY | getattr(os, "O_BINARY", 0))
        handle_owned = False
        return descriptor
    finally:
        if handle_owned:
            _close_handle(handle)

