create or replace function assign_action(p_id uuid, p_owner uuid, p_owner_name text) returns void
language plpgsql security definer set search_path = public as $$
declare
  v actions;
  v_owner_name text;
begin
  select * into v from actions where id = p_id for update;

  if not found then
    raise exception 'Action % does not exist.', p_id using errcode = 'P0002';
  end if;

  if not has_site_role(v.site_id, array['plant_manager', 'dept_head']::app_role[]) then
    raise exception '공장장 또는 실무부서장만 조치를 배정할 수 있습니다.';
  end if;

  if v.status not in ('open', 'returned') then
    raise exception 'open 또는 returned 상태의 조치만 배정할 수 있습니다.';
  end if;

  select profile.name
  into v_owner_name
  from profiles profile
  where profile.id = p_owner
    and profile.active
    and exists (
      select 1
      from role_assignments assignment
      where assignment.user_id = profile.id
        and assignment.role in ('env_officer', 'plant_manager')
        and assignment.scope = 'site'
        and assignment.site_id = v.site_id
    );

  if v_owner_name is null then
    raise exception '조치 담당자는 해당 사업장의 환경기술인 또는 공장장이어야 합니다.';
  end if;

  if p_owner_name is distinct from v_owner_name then
    raise exception '조치 담당자 이름이 사용자 프로필과 일치하지 않습니다.';
  end if;

  update actions
  set owner_id = p_owner,
      owner_name = v_owner_name,
      status = 'open',
      done_at = null,
      done_by = null,
      confirmed_by = null,
      confirmed_at = null,
      closed_by = null,
      closed_at = null,
      return_reason = null
  where id = p_id;
end $$;

create or replace function transition_era(p_id uuid, p_to era_status, p_reason text default null) returns void
language plpgsql security definer set search_path = public as $$
declare v era_assessments;
begin
  select * into v from era_assessments where id = p_id for update;
  if not found then
    raise exception 'ERA assessment % does not exist.', p_id using errcode = 'P0002';
  end if;

  if p_to = 'submitted' then
    if v.status not in ('draft', 'returned') then
      raise exception 'draft 또는 returned 상태의 ERA만 제출할 수 있습니다.';
    end if;
    if not has_site_role(v.site_id, array['env_officer', 'plant_manager']::app_role[]) then
      raise exception '환경기술인 또는 공장장만 ERA를 제출할 수 있습니다.';
    end if;
    update era_assessments
    set status = 'submitted', submitted_at = now(), return_reason = null
    where id = p_id;
  elsif p_to = 'reviewed' then
    if v.status <> 'submitted' then
      raise exception 'submitted 상태의 ERA만 검토할 수 있습니다.';
    end if;
    if not has_site_role(v.site_id, array['plant_manager']::app_role[]) then
      raise exception '공장장만 ERA를 검토할 수 있습니다.';
    end if;
    update era_assessments
    set status = 'reviewed', reviewed_by = auth.uid(), reviewed_at = now()
    where id = p_id;
  elsif p_to = 'approved' then
    if v.status <> 'reviewed' then
      raise exception 'reviewed 상태의 ERA만 승인할 수 있습니다.';
    end if;
    if not has_site_role(v.site_id, array['dept_head']::app_role[]) then
      raise exception '실무부서장만 ERA를 승인할 수 있습니다.';
    end if;
    update era_assessments
    set status = 'approved', approved_by = auth.uid(), approved_at = now()
    where id = p_id;
  elsif p_to = 'returned' then
    if v.status not in ('submitted', 'reviewed') then
      raise exception 'submitted 또는 reviewed 상태의 ERA만 반려할 수 있습니다.';
    end if;
    if not has_site_role(v.site_id, array['plant_manager', 'dept_head']::app_role[]) then
      raise exception '공장장 또는 실무부서장만 ERA를 반려할 수 있습니다.';
    end if;
    if coalesce(length(trim(p_reason)), 0) = 0 then
      raise exception '반려 사유를 입력하세요.';
    end if;
    update era_assessments
    set status = 'returned', return_reason = p_reason
    where id = p_id;
  else
    raise exception '지원하지 않는 ERA 대상 상태입니다. (%)', p_to;
  end if;
end $$;

create or replace function transition_action(p_id uuid, p_to action_status, p_reason text default null) returns void
language plpgsql security definer set search_path = public as $$
declare v actions;
begin
  select * into v from actions where id = p_id for update;
  if not found then
    raise exception 'Action % does not exist.', p_id using errcode = 'P0002';
  end if;

  if p_to = 'in_progress' then
    if v.status not in ('open', 'returned') then
      raise exception 'open 또는 returned 상태의 조치만 진행할 수 있습니다.';
    end if;
    if v.owner_id is null or v.owner_id <> auth.uid() then
      raise exception '조치 담당자만 진행·완료 처리할 수 있습니다.';
    end if;
    if not has_site_role(v.site_id, array['env_officer', 'plant_manager']::app_role[]) then
      raise exception '조치 담당자에게 유효한 사업장 역할이 없습니다.';
    end if;
    update actions set status = 'in_progress' where id = p_id;
  elsif p_to = 'done' then
    if v.status not in ('open', 'in_progress', 'returned') then
      raise exception 'open, in_progress 또는 returned 상태의 조치만 완료할 수 있습니다.';
    end if;
    if v.owner_id is null or v.owner_id <> auth.uid() then
      raise exception '조치 담당자만 진행·완료 처리할 수 있습니다.';
    end if;
    if not has_site_role(v.site_id, array['env_officer', 'plant_manager']::app_role[]) then
      raise exception '조치 담당자에게 유효한 사업장 역할이 없습니다.';
    end if;
    if not exists (
      select 1
      from attachments attachment
      where attachment.site_id = v.site_id
        and attachment.entity_type = 'action_after'
        and attachment.entity_id = p_id
        and attachment_evidence_is_valid(
          attachment.site_id,
          attachment.entity_type,
          attachment.entity_id,
          attachment.storage_path
        )
    ) then
      raise exception '조치 후 사진이 필요합니다.';
    end if;
    update actions
    set status = 'done',
        done_at = now(),
        done_by = auth.uid(),
        confirmed_by = null,
        confirmed_at = null,
        closed_by = null,
        closed_at = null,
        return_reason = null
    where id = p_id;
  elsif p_to = 'closed' then
    if v.status <> 'done' then
      raise exception 'done 상태의 조치만 종결할 수 있습니다.';
    end if;
    if not has_site_role(v.site_id, array['dept_head']::app_role[]) then
      raise exception '실무부서장만 조치를 종결할 수 있습니다.';
    end if;
    if v.confirmed_by is null then
      raise exception '조치는 공장장 확인 후 종결할 수 있습니다.';
    end if;
    update actions
    set status = 'closed', closed_by = auth.uid(), closed_at = now()
    where id = p_id;
  elsif p_to = 'returned' then
    if v.status <> 'done' then
      raise exception 'done 상태의 조치만 반려할 수 있습니다.';
    end if;
    if not has_site_role(v.site_id, array['plant_manager', 'dept_head']::app_role[]) then
      raise exception '공장장 또는 실무부서장만 조치를 반려할 수 있습니다.';
    end if;
    if coalesce(length(trim(p_reason)), 0) = 0 then
      raise exception '반려 사유를 입력하세요.';
    end if;
    update actions
    set status = 'returned',
        done_at = null,
        done_by = null,
        confirmed_by = null,
        confirmed_at = null,
        closed_by = null,
        closed_at = null,
        return_reason = p_reason
    where id = p_id;
  else
    raise exception '지원하지 않는 조치 대상 상태입니다. (%)', p_to;
  end if;
end $$;

create or replace function confirm_action(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v actions;
begin
  select * into v from actions where id = p_id for update;
  if not found then
    raise exception 'Action % does not exist.', p_id using errcode = 'P0002';
  end if;
  if v.status <> 'done' then
    raise exception '완료된 조치만 확인할 수 있습니다.';
  end if;
  if not has_site_role(v.site_id, array['plant_manager']::app_role[]) then
    raise exception '공장장만 완료된 조치를 확인할 수 있습니다.';
  end if;
  update actions
  set confirmed_by = auth.uid(), confirmed_at = now()
  where id = p_id;
end $$;

create or replace function confirm_obligation_task(p_task uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v obligation_tasks;
begin
  select * into v from obligation_tasks where id = p_task for update;
  if not found then
    raise exception 'Obligation task % does not exist.', p_task using errcode = 'P0002';
  end if;
  if v.status <> 'done' then
    raise exception '이행 등록된 건만 확인할 수 있습니다.';
  end if;
  if not has_site_role(v.site_id, array['plant_manager']::app_role[]) then
    raise exception '공장장만 이행 확인을 할 수 있습니다.';
  end if;
  if (select evidence_required from obligation_types where code = v.type_code)
     and not exists (
       select 1
       from attachments attachment
       where attachment.site_id = v.site_id
         and attachment.entity_type = 'obligation_task'
         and attachment.entity_id = p_task
         and attachment_evidence_is_valid(
           attachment.site_id,
           attachment.entity_type,
           attachment.entity_id,
           attachment.storage_path
         )
     ) then
    raise exception '증빙 파일이 없습니다.';
  end if;
  update obligation_tasks
  set status = 'confirmed', confirmed_by = auth.uid(), confirmed_at = now()
  where id = p_task;
end $$;

